// The one status mark: shape + colour + word. Used for the API connection,
// every run, and retries in flight, so "green" always means the same thing.
// kind: 'ok' | 'fail' | 'busy' | 'unknown'
export function statusMark(kind, label) {
  return `<span class="status status--${kind}"><span class="mark" aria-hidden="true"></span>${label}</span>`;
}

const CONNECTION = {
  checking: ['busy', 'Checking API'],
  up: ['ok', 'API connected'],
  down: ['fail', 'API unreachable'],
};

// connection: 'checking' | 'up' | 'down', from a real health() call in main.js.
export function renderBadge(connection, checkedAt) {
  const [kind, label] = CONNECTION[connection];
  const when = checkedAt ? `<span class="badge__time">checked ${checkedAt}</span>` : '';
  return `<span class="badge">${statusMark(kind, label)}${when}</span>`;
}

