:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

/* ── The status mark: shape + colour + word ─────────────────────────── */
.status { display: inline-flex; align-items: center; gap: var(--s2); font-weight: 500; white-space: nowrap; }
.mark { flex: none; width: 0.625rem; height: 0.625rem; }
.status--ok      { color: var(--ok); }
.status--fail    { color: var(--fail); }
.status--busy    { color: var(--busy); }
.status--unknown { color: var(--unknown); }
.status--ok .mark      { background: currentColor; border-radius: 50%; }
.status--fail .mark    { background: currentColor; width: 0.5rem; height: 0.5rem; margin-inline: 0.0625rem; transform: rotate(45deg); border-radius: 1px; }
.status--busy .mark    { border: 2px solid currentColor; border-radius: 50%; animation: pulse 1.4s var(--ease) infinite; }
.status--unknown .mark { border: 2px dashed currentColor; border-radius: 50%; }
@keyframes pulse { 50% { opacity: 0.35; } }

