  background: var(--surface);
  color: var(--muted); font-size: 0.8125rem; font-weight: 500;
}
.runs thead th.num { text-align: end; }
.runs tbody tr:last-child > * { border-bottom: 0; }
.runs tbody th { font-weight: 400; color: var(--muted); }
.runs tbody tr { transition: background-color 150ms var(--ease); }
.runs tbody tr:hover { background: var(--raised); }
.runs tr.is-failed { background: var(--fail-wash); }
.runs .service { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.runs .actions { text-align: end; }
.runs th:nth-child(1) { width: 18%; }
.runs th:nth-child(3) { width: 17%; }
.runs th:nth-child(4) { width: 12%; }
.runs th:nth-child(5) { width: 12%; }
.runs th:nth-child(6) { width: 9.5rem; }
.empty, .more { color: var(--muted); text-align: center !important; padding-block: var(--s6) !important; }
.more { padding-block: var(--s3) !important; }

.skeleton .bar { display: block; height: 0.75rem; width: 60%; border-radius: 3px; background: var(--raised); animation: pulse 1.4s var(--ease) infinite; }

/* Narrow screens: each run becomes a two-column record. */
@media (max-width: 40rem) {
  .page { padding: var(--s5) var(--s4); }
  .topbar { padding-inline: var(--s4); }
  .new-run { grid-template-columns: 1fr auto; width: 100%; }
  .new-run label { grid-column: 1 / -1; }
  .new-run .field-error { grid-column: 1 / -1; }
  .runs thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .runs, .runs tbody { display: block; }
  .runs tbody tr {
    display: grid; grid-template-columns: 1fr auto; gap: var(--s1) var(--s3);
    grid-template-areas: "svc state" "id dur" "start act";
    padding: var(--s3) var(--s4); border-bottom: 1px solid var(--line);
  }
  .runs tbody tr > * { padding: 0; border: 0; }
  .runs tbody .service { grid-area: svc; }
  .runs tbody .state { grid-area: state; text-align: end; }
  .runs tbody th { grid-area: id; }
  .runs tbody .duration { grid-area: dur; }
  .runs tbody .started { grid-area: start; align-self: center; color: var(--muted); }
  .runs tbody .actions { grid-area: act; }
  .runs tbody tr.skeleton, .runs tbody tr:has(.empty), .runs tbody tr:has(.more) { display: block; }
  .skeleton td { padding: var(--s1) 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

