.status--busy .mark    { border: 2px solid currentColor; border-radius: 50%; animation: pulse 1.4s var(--ease) infinite; }
.status--unknown .mark { border: 2px dashed currentColor; border-radius: 50%; }
@keyframes pulse { 50% { opacity: 0.35; } }

/* ── Top bar ────────────────────────────────────────────────────────── */
.topbar {
  display: flex; align-items: center; justify-content: space-between; gap: var(--s4);
  padding: var(--s3) var(--s5);
  border-bottom: 1px solid var(--line);
}
.wordmark { font-weight: 700; letter-spacing: -0.01em; font-size: 1rem; }
.badge {
  display: inline-flex; align-items: center; gap: var(--s3); flex-wrap: wrap;
  padding: var(--s1) var(--s3);
  border: 1px solid var(--line); border-radius: 999px;
  background: var(--surface);
}
.badge__time { color: var(--muted); font-size: 0.8125rem; font-variant-numeric: tabular-nums; }

/* ── Page head: the answer first, then the action ───────────────────── */
.page { max-width: 72rem; margin-inline: auto; padding: var(--s6) var(--s5); }
.page__head {
  display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between;
  gap: var(--s5); margin-bottom: var(--s5);
}
.summary { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s1) var(--s3); margin-top: var(--s2); font-size: 1rem; }
.summary__rest { color: var(--muted); }

.new-run { display: grid; grid-template-columns: auto minmax(8rem, 14rem) auto; align-items: center; gap: var(--s2) var(--s3); }
.new-run label { color: var(--muted); font-weight: 500; }
.new-run .field-error { grid-column: 2 / -1; }
input {
  min-height: var(--target); width: 100%;
  padding: 0 var(--s3);
  font: inherit; color: var(--ink);
  background: var(--bg);
  border: 1px solid var(--edge); border-radius: var(--radius);
}
input:hover:not(:disabled) { border-color: var(--muted); }
input[aria-invalid] { border-color: var(--fail); }
input:disabled { opacity: 0.55; cursor: not-allowed; }

/* ── One button ─────────────────────────────────────────────────────── */
.btn {
  min-height: var(--target); min-width: 5.5rem;
  padding: 0 var(--s3);
  font: 500 0.875rem/1 var(--font); color: var(--ink);
  background: var(--raised);
  border: 1px solid var(--edge); border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 150ms var(--ease), border-color 150ms var(--ease);
}
.btn:hover:not(:disabled) { background: var(--line); border-color: var(--muted); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn[aria-busy="true"] { cursor: progress; }
.btn--primary { background: var(--accent); color: var(--on-accent); border-color: var(--accent); font-weight: 600; }
.btn--primary:hover:not(:disabled) { background: var(--ring); border-color: var(--ring); }

.field-error { color: var(--fail); font-size: 0.8125rem; margin-top: var(--s1); }

/* ── Notice: honest about where the data came from ──────────────────── */
.notice {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s3) var(--s4);
  margin-bottom: var(--s4); padding: var(--s3) var(--s4);
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  color: var(--muted);
}
.notice p { max-width: 70ch; }
.notice strong { color: var(--busy); font-weight: 600; }

/* ── Runs table ─────────────────────────────────────────────────────── */
.runs {
  width: 100%; border-collapse: collapse; table-layout: fixed;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
}
.runs th, .runs td { padding: var(--s2) var(--s4); text-align: start; border-bottom: 1px solid var(--line); vertical-align: middle; }
.runs thead th {
  position: sticky; top: 0; z-index: 1;
  background: var(--surface);
  color: var(--muted); font-size: 0.8125rem; font-weight: 500;
}
.runs thead th.num { text-align: end; }
.runs tbody tr:last-child > * { border-bottom: 0; }
.runs tbody th { font-weight: 400; color: var(--muted); }
.runs tbody tr { transition: background-color 150ms var(--ease); }
.runs tbody tr:hover { background: var(--raised); }
.runs tr.is-failed { background: var(--fail-wash); }
.runs .service { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.runs .actions { text-align: end; }
.runs th:nth-child(1) { width: 18%; }
.runs th:nth-child(3) { width: 17%; }
.runs th:nth-child(4) { width: 12%; }
.runs th:nth-child(5) { width: 12%; }
.runs th:nth-child(6) { width: 9.5rem; }
.empty, .more { color: var(--muted); text-align: center !important; padding-block: var(--s6) !important; }
.more { padding-block: var(--s3) !important; }

.skeleton .bar { display: block; height: 0.75rem; width: 60%; border-radius: 3px; background: var(--raised); animation: pulse 1.4s var(--ease) infinite; }

/* Narrow screens: each run becomes a two-column record. */
@media (max-width: 40rem) {
  .page { padding: var(--s5) var(--s4); }
  .topbar { padding-inline: var(--s4); }
  .new-run { grid-template-columns: 1fr auto; width: 100%; }
  .new-run label { grid-column: 1 / -1; }
  .new-run .field-error { grid-column: 1 / -1; }
  .runs thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  .runs, .runs tbody { display: block; }
  .runs tbody tr {
    display: grid; grid-template-columns: 1fr auto; gap: var(--s1) var(--s3);
    grid-template-areas: "svc state" "id dur" "start act";
    padding: var(--s3) var(--s4); border-bottom: 1px solid var(--line);
  }
  .runs tbody tr > * { padding: 0; border: 0; }
  .runs tbody .service { grid-area: svc; }
  .runs tbody .state { grid-area: state; text-align: end; }
  .runs tbody th { grid-area: id; }
  .runs tbody .duration { grid-area: dur; }
  .runs tbody .started { grid-area: start; align-self: center; color: var(--muted); }
  .runs tbody .actions { grid-area: act; }
  .runs tbody tr.skeleton, .runs tbody tr:has(.empty), .runs tbody tr:has(.more) { display: block; }
  .skeleton td { padding: var(--s1) 0; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}

