.btn--primary:hover:not(:disabled) { background: var(--ring); border-color: var(--ring); }

.field-error { color: var(--fail); font-size: 0.8125rem; margin-top: var(--s1); }

/* ── Notice: honest about where the data came from ──────────────────── */
.notice {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--s3) var(--s4);
  margin-bottom: var(--s4); padding: var(--s3) var(--s4);
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
  color: var(--muted);
}
.notice p { max-width: 70ch; }
.notice strong { color: var(--busy); font-weight: 600; }

/* ── Runs table ─────────────────────────────────────────────────────── */
.runs {
  width: 100%; border-collapse: collapse; table-layout: fixed;
  background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius);
}
.runs th, .runs td { padding: var(--s2) var(--s4); text-align: start; border-bottom: 1px solid var(--line); vertical-align: middle; }
.runs thead th {
  position: sticky; top: 0; z-index: 1;
  background: var(--surface);
  color: var(--muted); font-size: 0.8125rem; font-weight: 500;
}
.runs thead th.num { text-align: end; }
