import { listRuns, retryRun, createRun, health } from './api/client.js';
import { renderBadge, statusMark } from './components/StatusBadge.js';

// Shown only when /api/runs doesn't answer, and labelled as sample data on screen.
const SAMPLE_RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];
const REFRESH_MS = 30_000;
const MAX_ROWS = 50;

const state = {
  connection: 'checking', // 'checking' | 'up' | 'down'
  checkedAt: null,
  mode: 'loading',        // 'loading' | 'live' | 'stale' | 'sample'
  runs: [],
  refreshedAt: null,
  retrying: new Set(),
  rowErrors: new Map(),
  creating: false,
  formError: '',
};

const $ = (sel) => document.querySelector(sel);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const clock = () => new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit' }).format(new Date());
const canAct = () => state.mode === 'live' || state.mode === 'stale';

function runKind(status) {
  if (status === 'passed') return 'ok';
  if (status === 'failed') return 'fail';
  if (status === 'running' || status === 'queued') return 'busy';
  return 'unknown';
}
const runLabel = (status) => esc(status ? status[0].toUpperCase() + status.slice(1) : 'Unknown');

// fetch() rejecting means nothing answered; a non-2xx means something did and said no.
const reason = (e) => (e instanceof TypeError || e instanceof SyntaxError ? "the API didn't answer" : e.message);

function announce(text) {
  $('#announcer').textContent = text;
}

function shell() {
  $('#app').innerHTML = `
    <header class="topbar">
      <span class="wordmark">pulse</span>
      <div id="connection"></div>
    </header>
    <main class="page">
      <div class="page__head">
        <div>
          <h1>Deploy runs</h1>
          <p id="summary" class="summary"></p>
        </div>
        <form id="new-run" class="new-run" novalidate>
          <label for="new-run-service">Service</label>
          <input id="new-run-service" name="service" list="services" autocomplete="off" spellcheck="false">
          <datalist id="services"></datalist>
          <button type="submit" class="btn btn--primary">New run</button>
          <p id="new-run-error" class="field-error" hidden></p>
        </form>
      </div>
      <div id="notice"></div>
      <p id="announcer" class="visually-hidden" role="status" aria-live="polite"></p>
      <table class="runs">
        <thead><tr>
          <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
          <th scope="col">Started</th><th scope="col" class="num">Duration</th>
          <th scope="col"><span class="visually-hidden">Actions</span></th>
        </tr></thead>
        <tbody id="runs"></tbody>
      </table>
    </main>`;

  $('#runs').addEventListener('click', (e) => {
    const b = e.target.closest('button[data-run]');
    if (b) retry(b.dataset.run);
  });
  $('#new-run').addEventListener('submit', onCreate);
  $('#notice').addEventListener('click', (e) => {
    if (e.target.closest('[data-refresh]')) refresh();
  });
}

function renderHeader() {
  $('#connection').innerHTML = renderBadge(state.connection, state.checkedAt);

  const failed = state.runs.filter((r) => runKind(r.status) === 'fail').length;
  const passed = state.runs.filter((r) => runKind(r.status) === 'ok').length;
  const total = state.runs.length;
  let summary = 'Loading runs…';
  if (state.mode !== 'loading') {
    summary = total === 0
      ? 'No runs yet.'
      : `${failed ? statusMark('fail', `${failed} failed`) : statusMark('ok', 'None failing')}
         <span class="summary__rest">${passed} passed · ${total} ${total === 1 ? 'run' : 'runs'}${state.mode === 'sample' ? ' · sample data' : ''}</span>`;
  }
  $('#summary').innerHTML = summary;
  document.title = canAct() && failed ? `${failed} failed · pulse` : 'pulse';

  const notices = {
    sample: `<strong>Live runs unavailable.</strong> /api/runs didn't answer, so this table shows sample runs from the demo. Retry and New run are off until it does.`,
    stale: `<strong>Couldn't refresh at ${state.checkedAt}.</strong> Showing runs as of ${state.refreshedAt}.`,
  };
  const notice = notices[state.mode];
  $('#notice').innerHTML = notice
    ? `<div class="notice" id="notice-text"><p>${notice}</p><button type="button" class="btn" data-refresh>Try again</button></div>`
    : '';
}

function row(r) {
  const kind = runKind(r.status);
  const pending = state.retrying.has(r.id);
  const err = state.rowErrors.get(r.id);
  const errId = `err-${esc(r.id)}`;
  const describedBy = err ? errId : !canAct() ? 'notice-text' : '';
  return `<tr class="${kind === 'fail' ? 'is-failed' : ''}">
    <th scope="row" class="mono">${esc(r.id)}</th>
    <td class="service">${esc(r.service)}</td>
    <td class="state">${pending ? statusMark('busy', 'Retrying') : statusMark(kind, runLabel(r.status))}</td>
    <td class="mono started">${esc(r.started)}</td>
    <td class="mono num duration">${esc(r.duration)}</td>
    <td class="actions">
      <button type="button" class="btn" data-run="${esc(r.id)}"
        ${pending || !canAct() ? 'disabled' : ''} ${pending ? 'aria-busy="true"' : ''}
        ${describedBy ? `aria-describedby="${describedBy}"` : ''}>Retry</button>
      ${err ? `<p class="field-error" id="${errId}">${esc(err)}</p>` : ''}
    </td>
  </tr>`;
}

const skeleton = () => `<tr class="skeleton" aria-hidden="true">${
  '<td><span class="bar"></span></td>'.repeat(6)}</tr>`;

function renderRuns() {
  // Keep keyboard focus on the same Retry button across re-renders.
  const focused = document.activeElement?.dataset?.run;
  const table = $('.runs');
  table.setAttribute('aria-busy', String(state.mode === 'loading'));

  let body;
  if (state.mode === 'loading') body = skeleton().repeat(4);
  else if (state.runs.length === 0) body = `<tr><td colspan="6" class="empty">No runs yet. Pick a service above and start one with New run.</td></tr>`;
  else {
    body = state.runs.slice(0, MAX_ROWS).map(row).join('');
    if (state.runs.length > MAX_ROWS) {
      body += `<tr><td colspan="6" class="more">Showing the latest ${MAX_ROWS} of ${state.runs.length} runs.</td></tr>`;
    }
  }
  $('#runs').innerHTML = body;

  $('#services').innerHTML = [...new Set(state.runs.map((r) => r.service))]
    .map((s) => `<option value="${esc(s)}">`).join('');

  if (focused) {
    const b = $(`button[data-run="${CSS.escape(focused)}"]`);
    if (b && !b.disabled) b.focus();
  }
}

function renderForm() {
  const input = $('#new-run-service');
  const button = $('#new-run button');
  const error = $('#new-run-error');
  input.disabled = !canAct();
  button.disabled = !canAct() || state.creating;
  button.textContent = state.creating ? 'Starting…' : 'New run';
  error.hidden = !state.formError;
  error.textContent = state.formError;
  if (state.formError) input.setAttribute('aria-invalid', 'true');
  else input.removeAttribute('aria-invalid');
  const describedBy = state.formError ? 'new-run-error' : !canAct() ? 'notice-text' : '';
  for (const el of [input, button]) {
    if (describedBy) el.setAttribute('aria-describedby', describedBy);
    else el.removeAttribute('aria-describedby');
  }
}

function renderAll() {
  renderHeader();
  renderRuns();
  renderForm();
}

async function refresh() {
  const was = state.connection;
  const [h, runs] = await Promise.allSettled([health(), listRuns()]);
  state.connection = h.status === 'fulfilled' ? 'up' : 'down';
  state.checkedAt = clock();

  if (runs.status === 'fulfilled' && Array.isArray(runs.value)) {
    state.runs = runs.value;
    state.mode = 'live';
    state.refreshedAt = state.checkedAt;
  } else if (state.mode === 'live' || state.mode === 'stale') {
    state.mode = 'stale';
  } else {
    state.runs = SAMPLE_RUNS;
    state.mode = 'sample';
  }

  if (was !== 'checking' && was !== state.connection) {
    announce(state.connection === 'up' ? 'API connected.' : 'API unreachable.');
  }
  renderAll();
}

async function retry(id) {
  if (state.retrying.has(id) || !canAct()) return;
  state.retrying.add(id);
  state.rowErrors.delete(id);
  renderRuns();
  try {
    const res = await retryRun(id);
    if (!res.ok) throw new Error(`the API answered ${res.status}`);
    announce(`Retry of ${id} started.`);
    state.retrying.delete(id);
    await refresh();
  } catch (e) {
    state.rowErrors.set(id, `Retry didn't start: ${reason(e)}.`);
    announce(`Retry of ${id} didn't start.`);
  } finally {
    state.retrying.delete(id);
    renderRuns();
  }
}

async function onCreate(e) {
  e.preventDefault();
  if (state.creating || !canAct()) return;
  const input = $('#new-run-service');
  const service = input.value.trim();
  if (!service) {
    state.formError = 'Enter the service to deploy.';
    renderForm();
    input.focus();
    return;
  }
  state.creating = true;
  state.formError = '';
  renderForm();
  try {
    const res = await createRun({ service });
    if (!res.ok) throw new Error(`the API answered ${res.status}`);
    input.value = '';
    announce(`Run for ${service} started.`);
    await refresh();
  } catch (err) {
    state.formError = `Run didn't start: ${reason(err)}.`;
  } finally {
    state.creating = false;
    renderForm();
  }
}

export function render() {
  shell();
  renderAll();
  refresh();
  setInterval(refresh, REFRESH_MS);
}

render();

